1	import { useEffect, useRef, useState } from "react";
2	import type { CSSProperties, FormEvent } from "react";
3	import { Player } from "./player";
4	import { initialState, reduce } from "./reduce";
5	import { CountUp, LiveClock, Note, Scribble, WindowBar } from "./motion";
6	import { SwarmView } from "./swarm";
7	import { formatClock, formatSkip } from "./timeline";
8	import { FAILURES, PIPELINE, stepIndex, type BrEvent, type CaseState, type ReplayFile, type ViewState } from "./types";
9	
10	type Selection = { kind: "agent"; id: string } | { kind: "case"; id: string; step?: string } | null;
11	
12	export interface Proof {
13	  fixed: number;
14	  cases: number;
15	  precision: number;
16	  claudeBefore: number;
17	  claudeAfter: number;
18	}
19	
20	function useReplayPlayer(replay: ReplayFile, opts: { compress: boolean; prerollMs: number; realLimitMs: number | null; loop: boolean }, active: boolean) {
21	  const [player, setPlayer] = useState<Player | null>(null);
22	  const [version, setVersion] = useState(0);
23	  const activeRef = useRef(active);
24	  const userPaused = useRef(false);
25	  activeRef.current = active;
26	
27	  useEffect(() => {
28	    const next = new Player(replay.events, replay.agents, opts);
29	    const off = next.subscribe(() => setVersion((value) => value + 1));
30	    next.seek(0);
31	    if (activeRef.current && !userPaused.current) next.play();
32	    setPlayer(next);
33	    return () => {
34	      off();
35	      next.destroy();
36	    };
37	    // The replay file is static for the life of the page.
38	    // eslint-disable-next-line react-hooks/exhaustive-deps
39	  }, [replay, opts.compress, opts.loop, opts.prerollMs, opts.realLimitMs]);
40	
41	  useEffect(() => {
42	    if (!player) return;
43	    if (active && !userPaused.current) player.play();
44	    if (!active) player.pause();
45	  }, [active, player]);
46	
47	  return { player, version, userPaused };
48	}
49	
50	function agentLabel(id?: string) {
51	  return id ? id.replace("research_", "").replaceAll("_", " ") : "";
52	}
53	
54	function agentNumber(id: string) {
55	  return id.match(/(\d+)$/)?.[1] ?? "·";
56	}
57	
58	function describe(event: BrEvent): string {
59	  const data = event.data;
60	  switch (event.type) {
61	    case "case.opened": return "Case opened";
62	    case "case.transition": return `${String(data.from ?? "")} → ${String(data.to ?? "")}`.replaceAll("_", " ");
63	    case "case.findings": return "Investigator findings in";
64	    case "case.verdict": return "Verifier verdict in";
65	    case "case.writeback": return "Written back to neatlogs";
66	    case "case.patched": return `Guardrail ${String(data.sha ?? "").slice(0, 7)}`;
67	    case "case.confirming": return "Confirmation re-runs";
68	    case "case.confirmed": return "Fix confirmed";
69	    case "case.remembered": return "Remembered in Brain";
70	    case "case.failed": return `Stopped at ${String(data.step ?? "a step")}`;
71	    case "agent.call": return `${String(data.tool ?? "call")} → ${String(data.service ?? "")}`;
72	    case "agent.blocked": return "Blocked by guardrail";
73	    default: return event.type;
74	  }
75	}
76	
77	const HEADLINE = ["Read", "what", "your", "agents", "did", "before", "someone", "else", "does."];
78	
79	export function Hero({ replay, proof }: { replay: ReplayFile; proof: Proof }) {
80	  const stage = useRef<HTMLElement>(null);
81	  const [active, setActive] = useState(true);
82	  const [counted, setCounted] = useState(false);
83	  const { player } = useReplayPlayer(replay, { compress: false, prerollMs: 1400, realLimitMs: 60_000, loop: true }, active);
84	
85	  useEffect(() => {
86	    const el = stage.current;
87	    if (!el) return;
88	    const io = new IntersectionObserver(([entry]) => setActive(entry.isIntersecting), { threshold: 0.15 });
89	    io.observe(el);
90	    const timer = window.setTimeout(() => setCounted(true), 700);
91	    return () => {
92	      io.disconnect();
93	      window.clearTimeout(timer);
94	    };
95	  }, []);
96	
97	  const read = () => ({ state: player?.state ?? initialState(replay.agents), now: player?.virt ?? 0 });
98	
99	  return (
100	    <section className="hero" id="top" ref={stage}>
101	      <div className="aura" aria-hidden="true"><i /><i /><i /></div>
102	      <div className="hero-grid" aria-hidden="true" />
103	      <div className="hero-inner">
104	        <div className="hero-copy">
105	          <a className="pill" href="#case">
106	            <span className="pill-tag">neatHack</span>
107	            Operator-side watchdog for agent fleets
108	            <span className="pill-arrow" aria-hidden="true">→</span>
109	          </a>
110	          <h1 className="hero-title" aria-label="Read what your agents did before someone else does.">
111	            {HEADLINE.map((word, index) => (
112	              <span key={word}>
113	                <span className="w" aria-hidden="true" style={{ ["--i" as string]: index } as CSSProperties}>
114	                  {word === "did" ? <Scribble>did</Scribble> : word}
115	                </span>
116	                {index < HEADLINE.length - 1 ? " " : ""}
117	              </span>
118	            ))}
119	          </h1>
120	          <p className="lede">Bladerunner reads every agent run's trace as it lands in neatlogs and checks it against that agent's policy. When a run breaks the rules, Bladerunner pauses it, proves the finding span by span, writes a guardrail, and confirms the fix holds.</p>
121	          <div className="hero-actions">
122	            <a className="btn" href="#case"><span className="btn-dot" aria-hidden="true" />Watch a case<span className="btn-arrow" aria-hidden="true">→</span></a>
123	            <a className="btn ghost" href="#exam">See the numbers</a>
124	          </div>
125	          <dl className="proof">
126	            <div><dt>Cases fixed on 11 Oct</dt><dd><CountUp value={proof.fixed} digits={0} play={counted} /><span>/{proof.cases}</span></dd></div>
127	            <div><dt>Precision on 102 traces</dt><dd><CountUp value={proof.precision} play={counted} /></dd></div>
128	            <div><dt>Claude false alarms</dt><dd>{proof.claudeBefore}<span className="to">→</span><CountUp value={proof.claudeAfter} digits={0} play={counted} /></dd></div>
129	          </dl>
130	        </div>
131	        <div className="hero-visual">
132	          <Note arrow="down-left" className="hero-note" delay={900}>the real 11 Oct run, replayed</Note>
133	          <div className="window glass">
134	            <WindowBar title="mission-control · replay">
135	              <LiveClock player={player} />
136	            </WindowBar>
137	            <div className="window-body stage hero-stage">
138	              <SwarmView read={read} onPick={() => document.getElementById("case")?.scrollIntoView({ behavior: "smooth" })} />
139	            </div>
140	            <p className="window-foot">First minute of 11 Oct 2026. The moving line is the watchdog reading traces.</p>
141	          </div>
142	          <EventStack player={player} />
143	        </div>
144	      </div>
145	    </section>
146	  );
147	}
148	
149	function EventStack({ player }: { player: Player | null }) {
150	  const [last, setLast] = useState(-1);
151	  useEffect(() => {
152	    if (!player) return;
153	    const id = window.setInterval(() => {
154	      const points = player.timeline.points;
155	      let index = -1;
156	      for (let i = 0; i < points.length; i += 1) {
157	        if (points[i].virt <= player.virt) index = i;
158	        else break;
159	      }
160	      setLast(index);
161	    }, 160);
162	    return () => window.clearInterval(id);
163	  }, [player]);
164	
165	  if (!player) return null;
166	  const points = player.timeline.points;
167	  const rows = [];
168	  for (let index = last; index >= 0 && index > last - 3; index -= 1) rows.push({ index, point: points[index] });
169	
170	  return (
171	    <ol className="events glass" aria-label="Latest events in the replay">
172	      {rows.length === 0 && <li className="idle"><span className="ev-dot" />Watching traces</li>}
173	      {rows.map(({ index, point }, row) => (
174	        <li key={index} className={row === 0 ? "fresh" : ""}>
175	          <span className="ev-dot" />
176	          <span className="ev-text">{describe(point.event)}</span>
177	          <span className="ev-meta">{agentLabel(point.event.agent)} · {formatClock(player.timeline.t0, point.real)}</span>
178	        </li>
179	      ))}
180	    </ol>
181	  );
182	}
183	
184	export function Mission({
185	  replay,
186	  liveOrigin,
187	  focusStep,
