    item.failure = { step: str(data, "step"), reason: str(data, "reason") };
    if (agent && agent.frozenAt == null) agent.frozenAt = at;
  } else if (event.type === "case.remembered") {
    item.remembered = str(data, "path") || str(data, "brain");
  }

