cat > src/zz_scratch.test.ts <<'EOF'
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { it } from "vitest";
import { agentPoint, rerunAlpha } from "./draw";
import { Player } from "./player";
import { formatClock, formatSkip } from "./timeline";

it("samples", () => {
  const replay = JSON.parse(readFileSync(fileURLToPath(new URL("../public/replay/efd78263e6d2.json", import.meta.url)), "utf-8"));
  for (const opts of [
    { compress: false, prerollMs: 1400, realLimitMs: 60_000, loop: true },
    { compress: true, prerollMs: 900, realLimitMs: null, loop: false },
  ]) {
    const p = new Player(replay.events, replay.agents, opts);
    const tl = p.timeline;
    console.log(`\n${opts.compress ? "MISSION" : "HERO"} duration ${(tl.duration / 1000).toFixed(0)}s points ${tl.points.length} skips ${tl.skips.map((s) => formatSkip(s.gap)).join(", ")}`);
    let peak = 0, outOfField = 0, bounces = 0;
    for (let v = 0; v <= tl.duration; v += 250) {
      p.seek(v);
      const on = Object.values(p.state.agents).filter((a) => a.rerun && rerunAlpha(a, v) > 0);
      peak = Math.max(peak, on.length);
      bounces += Object.values(p.state.agents).filter((a) => a.blockedAt != null && v >= a.blockedAt && v < a.blockedAt + 250).length;
      for (const a of Object.values(p.state.agents)) {
        if (rerunAlpha(a, v) === 0) continue;
        const { x, y } = agentPoint(a, 640, 420, v, true);
        if (x < 0 || y < 0 || x > 640 || y > 420) outOfField++;
      }
      if (v % 20000 === 0) {
        const s = p.state;
        const st = s.order.map((id) => s.cases[id].status).join(",");
        const live = replay.agents.map((id: string) => `${s.agents[id].trips.length}${s.agents[id].trail === "red" ? "R" : ""}${s.agents[id].cagedAt != null ? "C" : ""}`).join(" ");
        console.log(`${(v / 1000).toFixed(0).padStart(4)}s ${formatClock(tl.t0, realOf(tl, v))} live[${live}] reruns-on ${on.length} cases ${st || "-"}`);
      }
    }
    console.log(`peak reruns on stage ${peak}, bounce samples ${bounces}, dots outside field ${outOfField}`);
  }
});

function realOf(tl: { points: { virt: number; real: number }[] }, v: number) {
  let r = 0;
  for (const pt of tl.points) { if (pt.virt <= v) r = pt.real; else break; }
  return r;
}
EOF
npx vitest run src/zz_scratch.test.ts 2>&1 | grep -v "^$" | grep -vE "stdout|Test Files|Duration|Start at|RUN|✓" | head -60; rm src/zz_scratch.test.ts

